  return (
    <PageLayout title="Visuals">
      <Sections>
        <Section title="Logo">
          <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap' }}>
            <Box
              sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                p: 3,
                borderRadius: 1,
                border: '1px solid',
                borderColor: 'divider',
              }}
